class Solution {
  public int zigZagArrays(int n, int l, int r) {
    final long MOD = 1_000_000_007L;
    int K = r - l + 1;
    long[] up = new long[K];
    for (int v = 0; v < K; v++) up[v] = v;
    for (int len = 3; len <= n; len++) {
      // newUp[v] = sum of up[w] for w > K - 1 - v
      long[] suffix = new long[K + 1];
      for (int w = K - 1; w >= 0; w--) suffix[w] = (suffix[w + 1] + up[w]) % MOD;
      long[] next = new long[K];
      for (int v = 0; v < K; v++) next[v] = suffix[K - v];
      up = next;
    }
    long sum = 0;
    for (long v : up) sum += v;
    return (int) (sum % MOD * 2 % MOD);
  }
}
